"""Arithmetic hyperbolic Coxeter triangles with Vinberg field K = Q(O), exactly.

Triangle (p, q, r), Gram matrix with unit diagonal and off-diagonals -cos(pi/m).
Vinberg's criterion (Vinberg 1967; for triangles this is Takeuchi's criterion):
  * the Vinberg field K is generated by the cyclic products
    gamma(m) = 4cos^2(pi/m) and s = 8cos(pi/p)cos(pi/q)cos(pi/r);
  * cyclic products are algebraic integers (automatic: 2cos(pi/m) is);
  * the group is arithmetic iff for every embedding sigma != id of K, the
    sigma-conjugate form is positive semi-definite.
For a 3x3 Gram matrix with unit diagonal: det = 1 - sum(gamma)/4 - s/4. The 2x2
minors 1 - sigma(gamma)/4 are > 0 (sigma(gamma) = 2 + 2cos(2 pi j/m) < 4), so for
degree 2 the conjugate form is definite iff sigma(det) > 0 (and semi-definite iff
>= 0; equality cannot occur for a compact or cusped hyperbolic triangle with K of
degree 2, and is reported if it does).

Restriction: gamma(m) in K for each angle, so m ranges over R.gammas (a necessary
condition for K = Q(O)). s^2 = gamma_p gamma_q gamma_r; s in K iff that is a
square in K, found exactly (s > 0 at id).
"""
from __future__ import annotations

import itertools
import math
from typing import Dict, List, Optional

from .ring import Ring, El


def _sqrt_pos(z: El) -> Optional[El]:
    """The positive square root of z in O, or None (exact; floats only steer)."""
    R = z.R
    if z.is_zero():
        return R(0)
    if z.sign() < 0:
        return None
    if R.degree == 1:
        a = math.isqrt(z.coords()[0])
        return R(a) if R(a) * R(a) == z else None
    zc = z.conj()
    if zc.sign() < 0:
        return None
    x1, x2 = math.sqrt(float(z)), math.sqrt(float(zc))
    rd = math.sqrt(R.disc)
    w1, w2 = (R.c1 + rd) / 2, (R.c1 - rd) / 2
    for s2 in (x2, -x2):            # s = a + b w with s(id) = x1, s(sigma) = s2
        b = (x1 - s2) / (w1 - w2)
        a = x1 - b * w1
        for da in (-1, 0, 1):
            for db in (-1, 0, 1):
                s = R(round(a) + da, round(b) + db)
                if s.sign() > 0 and s * s == z:
                    return s
    return None


def triangle_data(R: Ring, p: int, q: int, r: int) -> Dict[str, object]:
    g = R.gammas
    gs = [g[p], g[q], g[r]]
    s = _sqrt_pos(gs[0] * gs[1] * gs[2])
    det = 1 - (gs[0] + gs[1] + gs[2]) / 4 - (s / 4 if s is not None else 0)
    out = {"angles": (p, q, r), "hyperbolic": None, "field_is_K": False,
           "arithmetic": False}
    if s is None:
        # 8 c_p c_q c_r is not in K, so the Vinberg field is larger than K
        out["reason"] = "cyclic product not in K"
        return out
    out["hyperbolic"] = det.sign() < 0
    irr = [x for x in gs + [s] if x.coords()[1] != 0]
    out["field_is_K"] = R.degree == 1 or bool(irr)
    if not out["hyperbolic"] or not out["field_is_K"]:
        return out
    cdet = det.conj()
    out["conj_det_sign"] = cdet.sign()
    out["arithmetic"] = cdet.sign() > 0
    out["compact"] = (1 / R(p) + 1 / R(q) + 1 / R(r) - 1).sign() < 0
    return out


def vinberg_field_triangles(R: Ring) -> Dict[str, List[tuple]]:
    """All hyperbolic triangles (p<=q<=r) with Vinberg field exactly K."""
    ms = sorted(R.gammas)
    ar, non = [], []
    for p, q, r in itertools.combinations_with_replacement(ms, 3):
        d = triangle_data(R, p, q, r)
        if not (d["hyperbolic"] and d["field_is_K"]):
            continue
        assert d["conj_det_sign"] != 0, (p, q, r)
        (ar if d["arithmetic"] else non).append((p, q, r))
    return {"arithmetic": ar, "non_arithmetic": non}


if __name__ == "__main__":
    import json
    import sys
    from .ring import get_ring
    print(json.dumps(vinberg_field_triangles(get_ring(int(sys.argv[1])))))
